clc; clearvars;
%%
root_dir = "..";
addpath(genpath(fullfile(root_dir, "\O3_Lidar\proc_functions")))
dataPath = fullfile(root_dir, "lidar_data\20251027");

data_format     = "bin"; %[control:dropdown:57a3]{"position":[19,24]}
prefix = "ol";

SNR_lim = 10;
n_shots = 1200;
tau = 1/(40e6);
dz = 3.75;
n_avg = 1;
fd = 270;

[an_R,pc_R,times,configs] = read_lidar_datafiles(dataPath,data_format,prefix);

n_bins = size(an_R,1);
n_prof = size(an_R,2);

h = (dz.*(1:n_bins))';
hkm = h./1000;

n_prof_avg = floor(n_prof / n_avg);

[an_bin,pc_P,times,an_B,pc_B] = preprocess(an_R,pc_R,times,dz,n_avg,n_shots,fd);
an_bin_bg = an_bin - an_B;
pc_P_bg = pc_P - pc_B;

an_bin_bg(an_bin_bg <= 0) = NaN;
pc_P_bg(pc_P_bg <= 0) = NaN;

an_mV_avg = scale_binary_analog(an_bin_bg,0,16,1201);
pc_p_avg = scale_binary_pc(pc_P_bg,3.75,1201);

etaQ_287 = 0.3;
etaQ_299 = 0.3;

mu_287 = 3e5;
mu_299 = 3e5;

id = 1; %[control:slider:4211]{"position":[6,7]}

an_287 = an_mV_avg(:,id,1);
an_299 = an_mV_avg(:,id,2);

pc_287 = pc_p_avg(:,id,1);
pc_299 = pc_p_avg(:,id,2);

Ik_287 = cathode_current(pc_287.*1e6,etaQ_287);
Ik_299 = cathode_current(pc_299.*1e6,etaQ_299);

Ip_287 = anode_current(Ik_287,mu_287);
Ip_299 = anode_current(Ik_299,mu_299);

bg_pc_287 = pc_B(1,id,1);
bg_pc_299 = pc_B(1,id,2);

N_287 = pc_287 .* 1e6 .* tau .* n_shots;
N_299 = pc_299 .* 1e6 .* tau .* n_shots;

NB_287 = bg_pc_287 .* 1e6 .* tau .* n_shots;
NB_299 = bg_pc_299 .* 1e6 .* tau .* n_shots;
%%
SNR_287_simple = sqrt(N_287);
SNR_287 = N_287 ./ sqrt(N_287 + NB_287);

SNR_299_simple = sqrt(N_299);
SNR_299 = N_299 ./ sqrt(N_299 + NB_299);
%%
dt = 1e6 * hkm.*1e3 * 2 / (3e8);

figure; %[output:1d22eb0a]
plot(dt,an_287,'DisplayName','287') %[output:1d22eb0a]
hold on %[output:1d22eb0a]
plot(dt,an_299,'DisplayName','299') %[output:1d22eb0a]
hold off %[output:1d22eb0a]
xlabel('Time (us)') %[output:1d22eb0a]
ylabel('Voltage (mV)') %[output:1d22eb0a]
grid on %[output:1d22eb0a]
legend %[output:1d22eb0a]
xlim([4 9]) %[output:1d22eb0a]
title('ADC Voltage') %[output:1d22eb0a]
figure; %[output:91dbef42]
semilogy(hkm,pc_287,'DisplayName','287') %[output:91dbef42]
hold on %[output:91dbef42]
plot(hkm,pc_299,'DisplayName','299') %[output:91dbef42]
hold off %[output:91dbef42]
xlabel('Alt (km)') %[output:91dbef42]
ylabel('Count Rate (MHz)') %[output:91dbef42]
grid on %[output:91dbef42]
legend %[output:91dbef42]
xlim([0 15]) %[output:91dbef42]
title('Count Rate') %[output:91dbef42]
figure; %[output:7c5efdb9]
semilogy(hkm,Ip_287 .* 1e3,'DisplayName','287') %[output:7c5efdb9]
hold on %[output:7c5efdb9]
plot(hkm,Ip_299 .* 1e3,'DisplayName','299') %[output:7c5efdb9]
hold off %[output:7c5efdb9]
xlabel('Alt (km)') %[output:7c5efdb9]
ylabel('Current (mA)') %[output:7c5efdb9]
grid on %[output:7c5efdb9]
legend %[output:7c5efdb9]
xlim([0 15]) %[output:7c5efdb9]
title('Anode Current') %[output:7c5efdb9]
%%
figure; %[output:54d8f7be]
semilogy(hkm,SNR_287,'DisplayName','287') %[output:54d8f7be]
hold on %[output:54d8f7be]
plot(hkm,SNR_299,'DisplayName','299') %[output:54d8f7be]
yline(SNR_lim,'--') %[output:54d8f7be]
hold off %[output:54d8f7be]
xlabel('Alt (km)') %[output:54d8f7be]
ylabel('Count Rate (MHz)') %[output:54d8f7be]
grid on %[output:54d8f7be]
legend %[output:54d8f7be]
xlim([0 15]) %[output:54d8f7be]
title("Basic SNR 287 and 299 nm") %[output:54d8f7be]
figure %[output:755dff13]
semilogy(hkm,SNR_287_simple,'DisplayName','without bg') %[output:755dff13]
hold on %[output:755dff13]
plot(hkm,SNR_287,'DisplayName','with bg') %[output:755dff13]
grid on %[output:755dff13]
legend %[output:755dff13]
xlim([0 15]) %[output:755dff13]
title("SNR 287 nm") %[output:755dff13]
figure %[output:58db2ff1]
semilogy(hkm,SNR_299_simple,'DisplayName','without bg') %[output:58db2ff1]
hold on %[output:58db2ff1]
plot(hkm,SNR_299,'DisplayName','with bg') %[output:58db2ff1]
grid on %[output:58db2ff1]
legend %[output:58db2ff1]
xlim([0 15]) %[output:58db2ff1]
title("SNR 299 nm") %[output:58db2ff1]
%%
N = 50;
M = 2*N+1;
n = -N:N;
b = sgolay(1,M);
Cn = b((M+1)/2,:);

figure; %[output:3a805d9a]
stem(n,b((M+1)/2,:)) %[output:3a805d9a]
%%
pc_287_filt = conv(pc(:,id,1),Cn,'same'); %[output:0c61a3f7]
pc_299_filt = conv(pc(:,id,2),Cn,'same');

SNR_287_filt = SNR_filt(N_287,NB_287,1,Cn);
SNR_299_filt = SNR_filt(N_299,NB_299,1,Cn);
%%
figure;
semilogy(hkm,pc_287_filt,'DisplayName','287')
hold on
plot(hkm,pc_299_filt,'DisplayName','299')
hold off
xlabel('Alt (km)')
ylabel('Count Rate (MHz)')
grid on
legend
xlim([0 30])
title('Count Rate Filtered')
figure;
semilogy(hkm,SNR_287_filt,'DisplayName','287')
hold on
plot(hkm,SNR_299_filt,'DisplayName','299')
hold off
xlabel('Alt (km)')
ylabel('Count Rate (MHz)')
grid on
legend
% xlim([0 30])
title('SNR with filter')
figure
semilogy(hkm,SNR_299,'DisplayName','without filter')
hold on
plot(hkm,SNR_299_filt,'DisplayName','with filter')
grid on
legend
xlim([0 15])
title("SNR 299 nm")
%%
function SNR = SNR_filt(S,B,L,Cn)
    SNR = NaN(size(S));
    
    M = length(Cn);
    N = (M-1)/2;
    
    for i = 1:length(S)
        if i >= N+1 && i < length(S)-N
            S_temp = S(i-N:i+N);

            top = Cn * S_temp;
            bot = sqrt(Cn.^2 * (S_temp+B));
            
            SNR(i) = sqrt(L) .* top ./ bot;
        end
    end
end

function out = correct_dt(data,dt)
    out = data./(1-data/dt);
end

function [out, bg] = rm_bg(data,bg_bins)
    bg = mean(data(bg_bins,:,:),1);
    
    out = data - bg;
end

function pc_cnvt = glue_loop(an,pc,R)
    pc_cnvt = NaN(size(pc));
    
    num_files = size(an,2);
    num_devices = size(an,3);

    for i = 1:num_files
        for j = 1:num_devices
            try
                pc_cnvt(:,i,j) = glue_an_pc(an(:,i,j),pc(:,i,j),R(1),R(2));
            catch ME
                disp(['error on file ', num2str(i), ', TR, ', num2str(j)]);
            end
        end
    end
end

function Ik = cathode_current(r,etaQ)
    e = 1.60217663e-19;

    Ik = r .* e .* etaQ;
end

function Ip = anode_current(Ik,mu)
    Ip = Ik .* mu;
end

